create or replace function "billing_ledger_balance_guard_fn"() returns trigger as $$
declare
	ledger_transaction_id uuid;
	entry_count bigint;
	debit_total numeric;
	credit_total numeric;
begin
	if TG_TABLE_NAME = 'billing_ledger_transaction' then
		ledger_transaction_id := NEW.id;
	else
		ledger_transaction_id := NEW."transactionId";
	end if;
	select count(*),
		coalesce(sum(entry.amount) filter (where entry.side = 'debit'), 0),
		coalesce(sum(entry.amount) filter (where entry.side = 'credit'), 0)
	into entry_count, debit_total, credit_total
	from "billing_ledger_entry" entry
	where entry."transactionId" = ledger_transaction_id;
	if entry_count < 2 or debit_total <> credit_total then
		raise exception 'Billing ledger transaction % is incomplete or unbalanced.', ledger_transaction_id
			using errcode = 'check_violation';
	end if;
	return null;
end; $$ language plpgsql;
create constraint trigger "billing_ledger_entry_balanced" after insert on "billing_ledger_entry"
	deferrable initially deferred for each row execute function "billing_ledger_balance_guard_fn"();

